(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.01+t*0.15)*8;
  const wy = Math.cos(y*0.016-t*0.3)*18 + Math.sin(x*0.014+t*0.32)*12 + Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.55)*110, 70+Math.cos(t*0.38)*55, 0.075, 2.1, 0.9],
    [320+Math.cos(t*0.48)*100, 170+Math.sin(t*0.65)*50, 0.09, 1.8, 1.1],
    [240+Math.sin(t*0.32+2)*150, 110+Math.cos(t*0.45+1)*95, 0.055, 2.5, 0.8],
    [100+Math.cos(t*0.75+1)*85, 190+Math.sin(t*0.58+3)*65, 0.11, 1.6, 1.2],
    [380+Math.sin(t*0.42+4)*95, 50+Math.cos(t*0.85+2)*75, 0.065, 2.8, 0.7],
    [200+Math.cos(t*0.3+5)*130, 210+Math.sin(t*0.52)*85, 0.085, 2.0, 1.0],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*60, 0.1, 1.9, 1.15],
    [420+Math.cos(t*0.44+2)*80, 200+Math.sin(t*0.56+4)*70, 0.07, 2.3, 0.85]
  ];
  let aS=0, iS=0, wS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave * w;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.7) * w;
    wS += Math.sin(d*f*1.3-t*sp*0.8+2.1) * (1-w)*0.5;
  }
  const n = src.length;
  aS/=n; iS/=n; wS/=n;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.75);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*1.05);
  const bg3 = Math.sin((sx+sy)*0.11+t*2.2)*0.25;
  const bg4 = Math.sin((sx-sy)*0.09-t*1.8)*0.25;
  const bg5 = Math.sin(sx*0.055+t*1.4)*Math.sin(sy*0.06-t*1.1)*0.3;
  const bg = (bg1+bg2)/2 + bg3 + bg4 + bg5;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.0)*0.4;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const react1 = Math.tanh((aS - iS*0.65 + bg*0.28 + spiral)*2.0);
  const react2 = Math.tanh((aS*0.8 + wS - iS*0.5 + bg*0.35 - spiral*0.4)*1.8);
  const feedback = Math.tanh((react1*1.2 + react2*0.8)*1.6);
  const cell1 = Math.sin(sx*0.16)*Math.sin(sy*0.16);
  const cell2 = Math.sin((sx+sy)*0.11+t*0.7)*Math.sin((sx-sy)*0.09-t*0.5);
  const cell3 = Math.sin(sx*0.08+sy*0.12+t*0.4)*Math.cos(sx*0.1-sy*0.07-t*0.3);
  const cell = Math.tanh((cell1+cell2*0.6+cell3*0.4)*1.4)*0.25;
  const edge = Math.abs(react1)>0.72 || Math.abs(react2)>0.65 ? 1.2 : 1.0;
  const glow = Math.max(0, 1-Math.abs(feedback))*0.15;
  const blend = feedback*0.65 + cell*0.2 + glow;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,35,85],[12,65,105],[18,105,125],
    [35,155,145],[120,185,130],[195,195,75],
    [225,160,55],[215,110,60],[185,65,70],
    [130,35,65],[70,18,55],[35,12,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const smooth = f*f*(3-2*f);
