    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*smooth)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*smooth)*lum*edge)|0
  ];
}
